                  "\n/* ========== CSS VARIABLES ========== */\n.cv-root {\n    --cv-bg: #111b21;\n    --cv-bg-secondary: #0b141a;\n    --cv-header-bg: #202c33;\n    --cv-border: #2a3942;\n    --cv-msg-out: #005c4b;\n    --cv-msg-out-tail: #005c4b;\n    --cv-msg-in: #202c33;\n    --cv-msg-in-tail: #202c33;\n    --cv-text: #e9edef;\n    --cv-text-secondary: #8696a0;\n    --cv-text-muted: rgba(255,255,255,0.6);\n    --cv-accent: #00a884;\n    --cv-accent-light: #06cf9c;\n    --cv-accent-blue: #53bdeb;\n    --cv-input-bg: #2a3942;\n    --cv-hover: rgba(255,255,255,0.05);\n    --cv-danger: #ea4335;\n    --cv-shadow: rgba(0,0,0,0.3);\n    --cv-overlay-bg: rgba(0,0,0,0.85);\n    --cv-emoji-bg: #202c33;\n    --cv-scrollbar: #374045;\n    --cv-scrollbar-hover: #4a5960;\n}\n\n.cv-root.cv-light {\n    --cv-bg: #f0f2f5;\n    --cv-bg-secondary: #efeae2;\n    --cv-header-bg: #f0f2f5;\n    --cv-border: #d1d7db;\n    --cv-msg-out: #d9fdd3;\n    --cv-msg-out-tail: #d9fdd3;\n    --cv-msg-in: #ffffff;\n    --cv-msg-in-tail: #ffffff;\n    --cv-text: #111b21;\n    --cv-text-secondary: #667781;\n    --cv-text-muted: rgba(0,0,0,0.45);\n    --cv-input-bg: #ffffff;\n    --cv-hover: rgba(0,0,0,0.05);\n    --cv-emoji-bg: #ffffff;\n    --cv-scrollbar: #c5c5c5;\n    --cv-scrollbar-hover: #a0a0a0;\n}\n\n/* ========== OVERLAY & MODAL ========== */\n.cv-overlay {\n    position: fixed;\n    inset: 0;\n    background: rgba(0,0,0,0.7);\n    backdrop-filter: blur(8px);\n    -webkit-backdrop-filter: blur(8px);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    z-index: 999999;\n    opacity: 0;\n    visibility: hidden;\n    transition: opacity .3s ease, visibility .3s ease;\n    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;\n}\n.cv-overlay.cv-visible {\n    opacity: 1;\n    visibility: visible;\n}\n\n.cv-modal {\n    width: 750px;\n    max-width: 96vw;\n    height: 88vh;\n    max-height: 900px;\n    background: var(--cv-bg);\n    border-radius: 16px;\n    display: flex;\n    flex-direction: column;\n    overflow: hidden;\n    transform: translateY(30px) scale(0.95);\n    transition: transform .3s cubic-bezier(0.4, 0, 0.2, 1);\n    box-shadow: 0 25px 100px rgba(0,0,0,0.5), 0 0 0 1px rgba(255,255,255,0.05);\n}\n.cv-overlay.cv-visible .cv-modal {\n    transform: translateY(0) scale(1);\n}\n\n/* ========== HEADER ========== */\n.cv-header {\n    background: var(--cv-header-bg);\n    padding: 12px 16px;\n    display: flex;\n    align-items: center;\n    gap: 14px;\n    border-bottom: 1px solid var(--cv-border);\n    min-height: 60px;\n}\n\n.cv-header-close {\n    width: 40px;\n    height: 40px;\n    border: none;\n    background: transparent;\n    color: var(--cv-text-secondary);\n    cursor: pointer;\n    border-radius: 50%;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    transition: all .2s ease;\n    flex-shrink: 0;\n}\n.cv-header-close:hover {\n    background: var(--cv-hover);\n    color: var(--cv-text);\n}\n.cv-header-close svg {\n    width: 24px;\n    height: 24px;\n}\n\n.cv-avatar {\n    width: 44px;\n    height: 44px;\n    border-radius: 50%;\n    background: linear-gradient(135deg, var(--cv-accent) 0%, var(--cv-accent-light) 100%);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    color: white;\n    font-weight: 600;\n    font-size: 18px;\n    flex-shrink: 0;\n    overflow: hidden;\n}\n.cv-avatar img {\n    width: 100%;\n    height: 100%;\n    object-fit: cover;\n}\n\n.cv-header-info {\n    flex: 1;\n    min-width: 0;\n}\n.cv-header-name {\n    color: var(--cv-text);\n    font-size: 16px;\n    font-weight: 500;\n    white-space: nowrap;\n    overflow: hidden;\n    text-overflow: ellipsis;\n}\n.cv-header-status {\n    color: var(--cv-text-secondary);\n    font-size: 13px;\n    margin-top: 1px;\n}\n\n/* ========== MESSAGES AREA ========== */\n.cv-messages {\n    flex: 1;\n    overflow-y: auto;\n    overflow-x: hidden;\n    padding: 12px 6%;\n    background: var(--cv-bg-secondary);\n    background-image: url(\"data:image/svg+xml,%3Csvg width='200' height='200' xmlns='http://www.w3.org/2000/svg'%3E%3Cdefs%3E%3Cpattern id='p' width='40' height='40' patternUnits='userSpaceOnUse'%3E%3Cpath d='M0 20h40M20 0v40' stroke='%23182229' stroke-width='0.5' fill='none'/%3E%3C/pattern%3E%3C/defs%3E%3Crect fill='url(%23p)' width='100%25' height='100%25'/%3E%3C/svg%3E\");\n}\n.cv-light .cv-messages {\n    background-image: url(\"data:image/svg+xml,%3Csvg width='200' height='200' xmlns='http://www.w3.org/2000/svg'%3E%3Cdefs%3E%3Cpattern id='p' width='40' height='40' patternUnits='userSpaceOnUse'%3E%3Cpath d='M0 20h40M20 0v40' stroke='%23d1d7db' stroke-width='0.3' fill='none'/%3E%3C/pattern%3E%3C/defs%3E%3Crect fill='url(%23p)' width='100%25' height='100%25'/%3E%3C/svg%3E\");\n}\n\n.cv-messages::-webkit-scrollbar { width: 6px; }\n.cv-messages::-webkit-scrollbar-track { background: transparent; }\n.cv-messages::-webkit-scrollbar-thumb { \n    background: var(--cv-scrollbar); \n    border-radius: 3px; \n}\n.cv-messages::-webkit-scrollbar-thumb:hover { \n    background: var(--cv-scrollbar-hover); \n}\n\n/* ========== DATE SEPARATOR ========== */\n.cv-date-sep {\n    display: flex;\n    justify-content: center;\n    margin: 16px 0;\n}\n.cv-date-badge {\n    background: var(--cv-header-bg);\n    color: var(--cv-text-secondary);\n    padding: 6px 14px;\n    border-radius: 8px;\n    font-size: 12px;\n    font-weight: 500;\n    box-shadow: 0 1px 3px var(--cv-shadow);\n    letter-spacing: 0.3px;\n}\n\n/* ========== MESSAGE WRAPPER ========== */\n.cv-msg-wrap {\n    display: flex;\n    margin-bottom: 2px;\n    padding: 0 2px;\n}\n.cv-msg-wrap.cv-out { justify-content: flex-end; }\n.cv-msg-wrap.cv-in { justify-content: flex-start; }\n.cv-msg-wrap.cv-has-reaction { margin-bottom: 18px; }\n\n/* ========== MESSAGE BUBBLE ========== */\n.cv-msg {\n    max-width: 65%;\n    min-width: 80px;\n    padding: 6px 7px 8px 9px;\n    border-radius: 8px;\n    position: relative;\n    box-shadow: 0 1px 2px var(--cv-shadow);\n    word-wrap: break-word;\n}\n\n.cv-out .cv-msg {\n    background: var(--cv-msg-out);\n    border-top-right-radius: 0;\n}\n.cv-in .cv-msg {\n    background: var(--cv-msg-in);\n    border-top-left-radius: 0;\n}\n\n/* Message tail */\n.cv-out.cv-first .cv-msg::before {\n    content: '';\n    position: absolute;\n    top: 0;\n    right: -8px;\n    width: 0;\n    height: 0;\n    border-top: 0px solid transparent;\n    border-bottom: 10px solid transparent;\n    border-left: 8px solid var(--cv-msg-out);\n}\n.cv-in.cv-first .cv-msg::before {\n    content: '';\n    position: absolute;\n    top: 0;\n    left: -8px;\n    width: 0;\n    height: 0;\n    border-top: 0px solid transparent;\n    border-bottom: 10px solid transparent;\n    border-right: 8px solid var(--cv-msg-in);\n}\n\n/* ========== MESSAGE CONTENT ========== */\n.cv-msg-text {\n    color: var(--cv-text);\n    font-size: 14.2px;\n    line-height: 1.4;\n    white-space: pre-wrap;\n}\n.cv-msg-text a {\n    color: var(--cv-accent-blue);\n    text-decoration: none;\n}\n.cv-msg-text a:hover {\n    text-decoration: underline;\n}\n\n.cv-msg-meta {\n    display: inline-flex;\n    align-items: center;\n    gap: 4px;\n    float: right;\n    margin: 4px 0 -4px 8px;\n    position: relative;\n}\n.cv-msg-time {\n    font-size: 11px;\n    color: var(--cv-text-muted);\n}\n.cv-in .cv-msg-time {\n    color: var(--cv-text-secondary);\n}\n\n/* ========== ACK STATUS ========== */\n.cv-ack {\n    display: inline-flex;\n    align-items: center;\n}\n.cv-ack svg {\n    width: 16px;\n    height: 11px;\n}\n.cv-ack-pending svg,\n.cv-ack-sent svg,\n.cv-ack-delivered svg {\n    color: var(--cv-text-muted);\n}\n.cv-ack-read svg {\n    color: var(--cv-accent-blue);\n}\n\n/* ========== LOADING & SYSTEM ========== */\n.cv-loading {\n    display: flex;\n    justify-content: center;\n    padding: 16px;\n}\n.cv-spinner {\n    width: 28px;\n    height: 28px;\n    border: 3px solid var(--cv-border);\n    border-top-color: var(--cv-accent);\n    border-radius: 50%;\n    animation: cv-spin .8s linear infinite;\n}\n@keyframes cv-spin {\n    to { transform: rotate(360deg); }\n}\n\n.cv-no-more {\n    text-align: center;\n    color: var(--cv-text-secondary);\n    font-size: 12px;\n    padding: 16px;\n    font-style: italic;\n}\n\n.cv-system {\n    display: flex;\n    justify-content: center;\n    margin: 12px 0;\n}\n.cv-system-badge {\n    background: var(--cv-header-bg);\n    color: var(--cv-text-secondary);\n    padding: 8px 16px;\n    border-radius: 8px;\n    font-size: 12px;\n    text-align: center;\n    max-width: 80%;\n    box-shadow: 0 1px 2px var(--cv-shadow);\n}\n\n/* ========== MEDIA MESSAGES ========== */\n.cv-media-wrap {\n    position: relative;\n    border-radius: 6px;\n    overflow: hidden;\n    margin-bottom: 4px;\n    background: rgba(0,0,0,0.1);\n}\n.cv-media-wrap img,\n.cv-media-wrap video {\n    display: block;\n    max-width: 330px;\n    max-height: 400px;\n    width: 100%;\n    border-radius: 6px;\n    cursor: pointer;\n    transition: transform .2s ease;\n}\n.cv-media-wrap img:hover,\n.cv-media-wrap video:hover {\n    transform: scale(1.02);\n}\n\n.cv-media-placeholder {\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    justify-content: center;\n    padding: 30px 50px;\n    background: rgba(0,0,0,0.2);\n    border-radius: 6px;\n    cursor: pointer;\n    transition: background .2s ease;\n    min-height: 120px;\n}\n.cv-media-placeholder:hover {\n    background: rgba(0,0,0,0.3);\n}\n.cv-media-placeholder-icon {\n    font-size: 36px;\n    margin-bottom: 8px;\n}\n.cv-media-placeholder-text {\n    color: var(--cv-text-secondary);\n    font-size: 12px;\n}\n\n.cv-media-loading {\n    position: absolute;\n    inset: 0;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    background: rgba(0,0,0,0.5);\n    border-radius: 6px;\n}\n\n.cv-sticker {\n    width: 160px;\n    height: 160px;\n    object-fit: contain;\n    background: transparent;\n}\n\n.cv-caption {\n    margin-top: 6px;\n}\n\n/* ========== VIDEO OVERLAY ========== */\n.cv-video-play {\n    position: absolute;\n    top: 50%;\n    left: 50%;\n    transform: translate(-50%, -50%);\n    width: 60px;\n    height: 60px;\n    background: rgba(0,0,0,0.6);\n    border-radius: 50%;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    cursor: pointer;\n    transition: all .2s ease;\n}\n.cv-video-play:hover {\n    background: rgba(0,0,0,0.8);\n    transform: translate(-50%, -50%) scale(1.1);\n}\n.cv-video-play svg {\n    width: 30px;\n    height: 30px;\n    fill: white;\n    margin-left: 4px;\n}\n\n/* ========== AUDIO PLAYER ========== */\n.cv-audio {\n    display: flex;\n    align-items: center;\n    gap: 10px;\n    padding: 8px 12px 8px 8px;\n    min-width: 280px;\n    background: rgba(0,0,0,0.05);\n    border-radius: 8px;\n}\n\n.cv-audio-btn {\n    width: 40px;\n    height: 40px;\n    border-radius: 50%;\n    background: var(--cv-accent);\n    border: none;\n    cursor: pointer;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    transition: all .2s ease;\n    flex-shrink: 0;\n}\n.cv-audio-btn:hover {\n    background: var(--cv-accent-light);\n    transform: scale(1.05);\n}\n.cv-audio-btn svg {\n    width: 18px;\n    height: 18px;\n    fill: white;\n}\n.cv-audio-btn.cv-playing svg {\n    width: 16px;\n    height: 16px;\n}\n\n.cv-audio-wave {\n    flex: 1;\n    height: 36px;\n    display: flex;\n    align-items: center;\n    gap: 2px;\n    cursor: pointer;\n    padding: 0 4px;\n}\n.cv-audio-bar {\n    flex: 1;\n    height: 100%;\n    background: var(--cv-text-secondary);\n    border-radius: 2px;\n    opacity: 0.4;\n    transition: all .15s ease;\n    max-width: 4px;\n}\n.cv-audio-bar.cv-active {\n    background: var(--cv-accent);\n    opacity: 1;\n}\n\n.cv-audio-info {\n    display: flex;\n    flex-direction: column;\n    align-items: flex-end;\n    gap: 2px;\n    min-width: 45px;\n}\n.cv-audio-time {\n    font-size: 11px;\n    color: var(--cv-text-secondary);\n    font-variant-numeric: tabular-nums;\n}\n.cv-audio-ptt-icon {\n    width: 20px;\n    height: 20px;\n    border-radius: 50%;\n    background: var(--cv-accent);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n}\n.cv-audio-ptt-icon svg {\n    width: 12px;\n    height: 12px;\n    fill: white;\n}\n\n/* ========== DOCUMENT ========== */\n.cv-doc {\n    display: flex;\n    align-items: center;\n    gap: 12px;\n    padding: 12px;\n    background: rgba(0,0,0,0.1);\n    border-radius: 8px;\n    min-width: 240px;\n    cursor: pointer;\n    transition: background .2s ease;\n}\n.cv-doc:hover {\n    background: rgba(0,0,0,0.15);\n}\n.cv-doc-icon {\n    width: 40px;\n    height: 48px;\n    background: var(--cv-accent);\n    border-radius: 4px;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    color: white;\n    font-size: 11px;\n    font-weight: 700;\n    flex-shrink: 0;\n}\n.cv-doc-info {\n    flex: 1;\n    min-width: 0;\n}\n.cv-doc-name {\n    color: var(--cv-text);\n    font-size: 13px;\n    white-space: nowrap;\n    overflow: hidden;\n    text-overflow: ellipsis;\n    margin-bottom: 2px;\n}\n.cv-doc-meta {\n    color: var(--cv-text-secondary);\n    font-size: 11px;\n}\n\n/* ========== DELETED MESSAGE ========== */\n.cv-deleted {\n    display: flex;\n    align-items: center;\n    gap: 6px;\n    color: var(--cv-text-secondary);\n    font-style: italic;\n    font-size: 13px;\n}\n.cv-deleted svg {\n    width: 18px;\n    height: 18px;\n    opacity: 0.7;\n}\n\n/* ========== QUOTED MESSAGE ========== */\n.cv-quote {\n    background: rgba(0,0,0,0.15);\n    border-left: 4px solid var(--cv-accent);\n    padding: 6px 10px;\n    border-radius: 4px;\n    margin-bottom: 6px;\n    cursor: pointer;\n    transition: background .2s ease;\n}\n.cv-quote:hover {\n    background: rgba(0,0,0,0.2);\n}\n.cv-quote-author {\n    color: var(--cv-accent);\n    font-size: 12px;\n    font-weight: 500;\n    margin-bottom: 2px;\n}\n.cv-quote-text {\n    color: var(--cv-text-secondary);\n    font-size: 12px;\n    display: -webkit-box;\n    -webkit-line-clamp: 2;\n    -webkit-box-orient: vertical;\n    overflow: hidden;\n}\n\n/* ========== REACTION ========== */\n.cv-reaction {\n    position: absolute;\n    bottom: -14px;\n    right: 8px;\n    background: var(--cv-header-bg);\n    padding: 2px 6px;\n    border-radius: 12px;\n    font-size: 16px;\n    box-shadow: 0 2px 6px var(--cv-shadow);\n    border: 1px solid var(--cv-border);\n}\n\n/* ========== FULLSCREEN MEDIA VIEWER ========== */\n.cv-viewer {\n    position: fixed;\n    inset: 0;\n    background: var(--cv-overlay-bg);\n    z-index: 2147483647;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    opacity: 0;\n    visibility: hidden;\n    transition: all .3s ease;\n}\n.cv-viewer.cv-visible {\n    opacity: 1;\n    visibility: visible;\n}\n.cv-viewer-close {\n    position: absolute;\n    top: 20px;\n    right: 20px;\n    width: 44px;\n    height: 44px;\n    background: rgba(255,255,255,0.1);\n    border: none;\n    border-radius: 50%;\n    cursor: pointer;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    transition: all .2s ease;\n    z-index: 10;\n}\n.cv-viewer-close:hover {\n    background: rgba(255,255,255,0.2);\n}\n.cv-viewer-close svg {\n    width: 24px;\n    height: 24px;\n    fill: white;\n}\n.cv-viewer-content {\n    max-width: 90vw;\n    max-height: 90vh;\n    object-fit: contain;\n    border-radius: 8px;\n    box-shadow: 0 20px 60px rgba(0,0,0,0.5);\n}\n.cv-viewer video {\n    max-width: 90vw;\n    max-height: 90vh;\n}\n";
                document.head.appendChild(e);
